uranca","title":"Segurança durante a remada","body":"O uso de colete salva-vidas é obrigatório durante a atividade na água. Antes da saída, nossa equipe apresentará as orientações de segurança."},{"id":"alimentacao","title":"Alimentação inclusa","body":"Ao final da programação, teremos um momento especial de integração com lanche saudável oferecido pela Nutre Congelados Saudáveis."},{"id":"clima","title":"Condições climáticas","body":"A segurança e o bem-estar de todos vêm em primeiro lugar. Caso as condições climáticas impeçam a realização segura da experiência, o evento será reagendado e os participantes serão comunicados pela organização."},{"id":"cancelamento","title":"Política de cancelamento","body":"Você pode solicitar o cancelamento até 5 de novembro de 2026, às 12h00 (horário de Brasília), escolhendo entre crédito para utilizar em outras experiências da Alma Azul ou solicitação de reembolso com nossa equipe.\n\nApós esse prazo, entre em contato conosco para avaliação do seu caso."}]},"arrival":{"startTime":"05:30","toleranceUntil":"05:50"},"cancellation":{"deadline":"2026-11-05T12:00:00-03:00","timeZone":"America/Sao_Paulo","summary":"crédito para utilizar em outras experiências da Alma Azul ou solicitação de reembolso com nossa equipe"},"reservation":{"eyebrow":"Sua próxima pausa tem data marcada","title":"Garanta a sua vaga","ctaLabel":"Garantir minha vaga","maxPerOrder":6,"notice":"Traga seu próprio tapete para a prática de Superioga. A organização não disponibilizará tapetes.","image":{"src":"/images/eventos/essencia/capsula-pier-amanhecer.jpg","alt":"Píer do Cápsula Bar avançando sobre o Lago Paranoá ao amanhecer"}}}}$json$::jsonb from ev) and (select public.experience_editorial_is_publishable(editorial_content) from ev) then 'OK' else 'FALHOU' end
  union all
  select 'SESSAO_FECHADA',
         coalesce((select string_agg(status || ' ' || to_char(starts_at at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI') || ' ' || duration_minutes || 'min ' || price_cents || ' centavos ' || capacity || ' vagas', '; ') from ses), 'nenhuma'),
         case when (select count(*) from ses) = 1
               and (select status = 'CLOSED' and starts_at = '2026-11-07T08:30:00.000Z'::timestamptz and duration_minutes = 210
                           and price_cents = 15000 and capacity = 24 from ses) then 'OK' else 'FALHOU' end
  union all
  select 'LIMITE_POR_PEDIDO_E_PRAZO',
         coalesce((select 'até ' || (editorial_content #>> '{event,reservation,maxPerOrder}') || ' por pedido; cancelamento até ' || (editorial_content #>> '{event,cancellation,deadline}') from ev), 'ausente'),
         case when (select (editorial_content #>> '{event,reservation,maxPerOrder}') = '6'
                           and (editorial_content #>> '{event,cancellation,deadline}') = '2026-11-05T12:00:00-03:00' from ev) then 'OK' else 'FALHOU' end
  union all
  select 'RASCUNHO_INATIVO',
         coalesce((select coalesce('active=' || (to_jsonb(ev) ->> 'active'), 'sem a coluna active') from ev), 'ausente'),
         case when (select coalesce(to_jsonb(ev) ->> 'active', 'false') = 'false' from ev) then 'OK' else 'FALHOU' end
  union all
  select 'NADA_PUBLICO',
         (select count(*)::text from public.list_public_events()) || ' evento(s) nas leituras públicas; interruptor '
           || coalesce((select case when publication_enabled then 'ligado' else 'desligado' end from public.special_event_settings where singleton), 'ausente'),
         case when not exists (select 1 from public.list_public_events()) and (select publication_enabled from public.special_event_settings where singleton) is false then 'OK' else 'FALHOU' end
  union all
  select 'SEM_RESERVAS_NEM_LISTA',
         (select count(*)::text from public.reservations r join ses on ses.id = r.session_id) || ' reserva(s), '
           || (select count(*)::text from public.waitlist_entries we join ses on ses.id = we.session_id) || ' inscrição(ões)',
         case when not exists (select 1 from public.reservations r join ses on ses.id = r.session_id)
               and not exists (select 1 from public.waitlist_entries we join ses on ses.id = we.session_id) then 'OK' else 'FALHOU' end
  union all
  select 'AUDITORIA',
         (select count(*)::text from public.admin_audit_log a join ev on ev.id = a.entity_id where a.action = 'EVENT_CREATED') || ' registro(s) EVENT_CREATED',
         case when (select count(*) from public.admin_audit_log a join ev on ev.id = a.entity_id where a.action = 'EVENT_CREATED') = 1 then 'OK' else 'FALHOU' end
  union all
  select 'LISTAGENS_REGULARES',
         (select count(*)::text from public.list_public_regular_experiences()) || ' experiências, ' || (select count(*)::text from public.list_public_regular_catalog()) || ' no catálogo',
         'OK'
  union all
  select 'RESERVAS_POR_STATUS',
         (select string_agg(status || '=' || n, ', ' order by status) from (select status::text, count(*) n from public.reservations group by 1) x),
         'OK'
  union all
  select 'INSCRICOES_DA_LISTA_POR_STATUS',
         coalesce((select string_agg(status || '=' || n, ', ' order by status) from (select status::text, count(*) n from public.waitlist_entries group by 1) x), 'nenhuma'),
         'OK'
)
select check_name, result, status from checks
union all
select 'ESSENCIA_CADASTRO_POSTCHECK_OK',
       (select count(*) filter (where status = 'FALHOU')::text || ' falha(s), ' || count(*) filter (where status = 'ATENCAO')::text || ' ponto(s) de atenção' from checks),
       case when exists (select 1 from checks where status = 'FALHOU') then 'FALHOU' else 'OK' end;
